"""CI replay: train artifacts already generated by train.py, then score and check."""
import hashlib,json
from pathlib import Path
try:
 from .score import score
 from .beam_verify import beam,exact
except ImportError:
 from score import score
 from beam_verify import beam,exact
P=Path(__file__).parent
rows=[];hashes={}
for seed in range(216,240):
 path=P/f"CHECKPOINT_SEED_{seed}.json"
 hashes[path.name]=hashlib.sha256(path.read_bytes()).hexdigest()
 cp=json.loads(path.read_text())[0]
 pred=score(cp,include_increment=seed>=224)
 witness=beam(cp,128)
 verification=exact(cp,witness["word"]) if witness["found"] else None
 if verification is not None:assert verification["failure"]
 rows.append(dict(seed=seed,width=len(cp["parameters"]["w"]),train_mse=cp["train_mse"],prediction=pred,witness=witness,exact=verification))
 print(seed,pred["predict_failure"],witness["depth"],flush=True)
(P/"CI_FULL_RESULTS.json").write_text(json.dumps(rows,indent=2)+"\n")
(P/"CI_CHECKPOINT_HASHES.json").write_text(json.dumps(hashes,indent=2)+"\n")
